package org.acme.billing;

public class Invoice {
    public int total(int[] lines) {
        int sum = 0;
        for (int line : lines) {
            sum += line;
        }
        return sum;
    }
}

package org.acme.billing;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class InvoiceTest {
    @Test
    void addsLines() {
        assertEquals(6, new Invoice().total(new int[] {1, 2, 3}));
    }
}

